package com.djibtout.backend;
import com.djibtout.backend.entity.Campaign;import com.djibtout.backend.repository.CampaignRepository;import org.springframework.boot.CommandLineRunner;import org.springframework.stereotype.Component;import java.util.List;
// Donnees de demonstration : ce composant ne doit jamais s'executer
// ailleurs qu'en developpement. L'expression de profils exige `seed` ET
// `local` : demander `seed` seul (ou avec `prod`) ne suffit pas, sinon un
// compte vendeur au mot de passe connu apparaitrait dans toute base vide,
// production comprise.
@Component @org.springframework.context.annotation.Profile("seed & local") public class CampaignSeeder implements CommandLineRunner{private final CampaignRepository repository;public CampaignSeeder(CampaignRepository r){repository=r;}public void run(String...args){if(repository.count()>0)return;repository.saveAll(List.of(campaign("Offre de la semaine","La technologie qui vous rapproche","Smartphones et accessoires à prix DjibTout.","/category/electronique",0,"from-[#063b8f] via-[#0052cc] to-[#2c7ef8]"),campaign("Maison & confort","Tout pour une maison qui vous ressemble","Équipez chaque pièce avec nos sélections.","/category/maison",1,"from-[#075985] via-[#0891b2] to-[#22d3ee]"),campaign("DjibTout Premium","Plus rapide, plus simple, plus avantageux","Livraison prioritaire et offres membres.","/account",2,"from-[#312e81] via-[#4338ca] to-[#818cf8]")));}private Campaign campaign(String badge,String title,String subtitle,String link,int order,String gradient){Campaign c=new Campaign();c.setBadge(badge);c.setTitle(title);c.setSubtitle(subtitle);c.setLinkUrl(link);c.setDisplayOrder(order);c.setGradient(gradient);return c;}}
